// ─── File: AbstractSealedDemo.java ───
// Single runnable file with multiple top-level package-private classes.
package com.bank.abssealed;

import java.math.BigDecimal;
import java.util.List;
import java.util.logging.*;

public class AbstractSealedDemo {
    private static final Logger log = Logger.getLogger(AbstractSealedDemo.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // new Account(...) is IMPOSSIBLE — the base is abstract. Only products open.
        InterestService service = new InterestService();
        List<Account> accounts = List.of(
            new SavingsAccount("SAV2001", "Rajesh Kumar", new BigDecimal("1000000")),
            new CurrentAccount("CUR3001", "Priya Sharma", new BigDecimal("250000")),
            new LoanAccount("LN5001", "Rajesh Kumar", new BigDecimal("3000000")));

        for (Account a : accounts) {
            BigDecimal interest = service.cappedMonthlyInterest(a);
            log.info(() -> a.getClass().getSimpleName() + " " + a.id()
                    + " monthly interest = Rs." + interest);
        }
    }
}

// ─── Would be in model/Account.java ───
// ABSTRACT + SEALED: cannot be instantiated directly, and only the three
// listed products may extend it. Holds shared state and a concrete method.
abstract sealed class Account permits SavingsAccount, CurrentAccount, LoanAccount {
    private final String id;
    private final String holder;
    private BigDecimal balance;

    // Constructor exists even though the class is abstract — subclasses call super().
    protected Account(String id, String holder, BigDecimal balance) {
            this.id = id;
            this.holder = holder
            this.balance = balance;
    }
    String id() { return id; }
    String holder() { return holder; }
    BigDecimal balance() { return balance; }

    // Concrete shared behaviour.
    void credit(BigDecimal amount) { balance = balance.add(amount); }

    // Abstract behaviour each product MUST implement (classic polymorphism).
    abstract BigDecimal monthlyInterest();
}

// ─── Would be in model/SavingsAccount.java ───
final class SavingsAccount extends Account {
    SavingsAccount(String id, String holder, BigDecimal balance) { super(id, holder, balance); }
    @Override BigDecimal monthlyInterest() {               // 3% p.a. → /12
        return balance().multiply(new BigDecimal("0.03"))
                .divide(new BigDecimal("12"), 2, java.math.RoundingMode.HALF_UP);
    }
}

// ─── Would be in model/CurrentAccount.java ───
final class CurrentAccount extends Account {
    CurrentAccount(String id, String holder, BigDecimal balance) { super(id, holder, balance); }
    @Override BigDecimal monthlyInterest() { return BigDecimal.ZERO; } // current earns none
}

// ─── Would be in model/LoanAccount.java ───
final class LoanAccount extends Account {
    LoanAccount(String id, String holder, BigDecimal balance) { super(id, holder, balance); }
    @Override BigDecimal monthlyInterest() {               // 9% p.a. charged → /12
        return balance().multiply(new BigDecimal("0.09"))
                .divide(new BigDecimal("12"), 2, java.math.RoundingMode.HALF_UP);
    }
}

// ─── Would be in service/InterestService.java ───
class InterestService {
    private static final BigDecimal CAP = new BigDecimal("20000.00");
    // Exhaustive switch over the abstract sealed family — no default needed.
    BigDecimal cappedMonthlyInterest(Account a) {
        BigDecimal raw = switch (a) {
            case SavingsAccount s -> s.monthlyInterest();
            case CurrentAccount c -> c.monthlyInterest();
            case LoanAccount l    -> l.monthlyInterest();
        };
        return raw.min(CAP);   // regulatory cap applied centrally
    }
}

// ─── Would be in util/BankLogFormatter.java ───
class BankLogFormatter extends java.util.logging.Formatter {
    @Override public String format(java.util.logging.LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
